export interface ArtCap { pattern: RegExp; max: number; lazy?: boolean }
export interface ArtImage { name: string; w: number; h: number }

export const ART_CAPS: ArtCap[] = [
  { pattern: /^art-/, max: 128 },
  { pattern: /^item-/, max: 128 },
  { pattern: /^cosmetic-/, max: 128 },
  { pattern: /^fish-/, max: 128 },
  { pattern: /^(coin|potion-drop)\./, max: 96 },
  { pattern: /^panda-/, max: 384 },
  { pattern: /^npc-/, max: 256 },
  { pattern: /^death-panda\./, max: 256 },
  { pattern: /^fx-/, max: 256 },
  { pattern: /^splash\./, max: 1024 },
  { pattern: /^bg-/, max: 1024, lazy: true },
  { pattern: /^biome-/, max: 1024, lazy: true },
  { pattern: /^town-/, max: 1024, lazy: true },
  { pattern: /^(map-|mapfill-)/, max: 1024, lazy: true },
]

export const DEFAULT_CAP = 256
export const BOOT_BUDGET_MB = 45

